self.onmessage = async ({ data }) => {
    try {
        const { analyze_gpx } = await import("../rust/pkg/adventure_analysis");
        const start = performance.now();
        const analysis = JSON.parse(analyze_gpx(data.xml));
        const response = { id: data.id, analysis, elapsedMs: performance.now() - start };
        self.postMessage(response);
    }
    catch (error) {
        const response = { id: data.id, error: error instanceof Error ? error.message : String(error) };
        self.postMessage(response);
    }
};
export {};
